// TenancyServer is the server API for Tenancy service.
// All implementations must embed UnimplementedTenancyServer
// for forward compatibility.
//
// Tenancy is the directory's tenancy (docs/hosted.md, "Tenancy, as built"): organizations, their
// members and teams, every repository's entry and its names, and the roles granted on it. A person
// calls it as themselves; ok control and the SCM call it for a person they authenticated
// (for_person_id), and the SCM reserves and activates the entries of repositories it makes.
// Authorize decides what each caller may do to a repository; an organization's owners manage it.
type TenancyServer interface {
	// CreateOrganization makes an organization the person owns: a hosted service's people only; an
	// installation has one.
	CreateOrganization(context.Context, *CreateOrganizationRequest) (*Organization, error)
	GetOrganization(context.Context, *GetOrganizationRequest) (*Organization, error)
	// DeleteOrganization deletes an organization (its owners'): suspended, its repositories deleted,
	// restorable for 30 days by an owner (RestoreOrganization); then for good — its handle retired,
	// its teams, robots, apps, identity provider, and the people it provided gone. An installation's
	// is never deleted.
	DeleteOrganization(context.Context, *OrganizationDeletionRequest) (*DeletionInfo, error)
	RestoreOrganization(context.Context, *OrganizationDeletionRequest) (*RestoreResponse, error)
	// DeleteAccount deletes the caller's own account, in a hosted service: suspended, its sessions
	// ended, its repositories deleted, restorable for 30 days by an administrator
	// (Admin.RestoreAccount); then for good — its handle retired, its credentials and tokens revoked.
	// Some organization's only owner is refused; so is a person a system of record or an
	// organization's identity provider made, which deletes them.
	DeleteAccount(context.Context, *DeleteAccountRequest) (*DeletionInfo, error)
	// UpdateOrganization changes an organization's settings: its owners.
	UpdateOrganization(context.Context, *UpdateOrganizationRequest) (*Organization, error)
	// SetRegion sets the region an owner's new repositories are placed in (docs/hosted.md, "Cells,
	// as built"): a person's own, or an organization's, by its owners; empty for the directory's
	// default. One no cell is in is refused. GetRegion reads it, and where new ones go.
	SetRegion(context.Context, *SetRegionRequest) (*Region, error)
	GetRegion(context.Context, *GetRegionRequest) (*Region, error)
	// SetSecretsRoot names an organization's own root for its repositories' secrets — a key in its
	// own KMS that ok's workload is granted to use (docs/secrets.md, "Keys"): its owners'. Empty
	// forgets it, for the installation's. GetSecretsRoot reads it: its members'.
	SetSecretsRoot(context.Context, *SetSecretsRootRequest) (*SecretsRoot, error)
	GetSecretsRoot(context.Context, *GetSecretsRootRequest) (*SecretsRoot, error)
	// ListMembers lists an organization's members: for its members.
	ListMembers(context.Context, *ListMembersRequest) (*ListMembersResponse, error)
	// SetMember makes a person a member or an owner: its owners. An installation's members are its
	// people and robots, and its owners its administrators: none is set here.
	SetMember(context.Context, *SetMemberRequest) (*SetMemberResponse, error)
	// RemoveMember takes a person out: its owners, or the person themselves.
	RemoveMember(context.Context, *RemoveMemberRequest) (*RemoveMemberResponse, error)
	// Teams are an organization's owners' to make and fill; its members list them. An installation's
	// teams are its groups, which the groups-and-ACLs tree declares and the system of record syncs.
	CreateTeam(context.Context, *CreateTeamRequest) (*Team, error)
	ListTeams(context.Context, *ListTeamsRequest) (*ListTeamsResponse, error)
	AddTeamMember(context.Context, *TeamMemberRequest) (*Team, error)
	RemoveTeamMember(context.Context, *TeamMemberRequest) (*Team, error)
	DeleteTeam(context.Context, *DeleteTeamRequest) (*DeleteTeamResponse, error)
	// An organization's robots — CI identities, deploy agents — are its owners' to make, certify, and
	// delete; its members list them. One is named <name>.<org>.robot.<domain>, and reaches the
	// organization's repositories through its grants alone. An installation's robots are its
	// administrators' (Admin).
	CreateOrganizationRobot(context.Context, *CreateOrganizationRobotRequest) (*OrganizationRobot, error)
	ListOrganizationRobots(context.Context, *ListOrganizationRobotsRequest) (*ListOrganizationRobotsResponse, error)
	// CertifyOrganizationRobot enrolls a key one of the organization's robots holds, and issues its
	// first certificate, which it renews as a command line does.
	CertifyOrganizationRobot(context.Context, *CertifyOrganizationRobotRequest) (*CertifyRobotResponse, error)
	DeleteOrganizationRobot(context.Context, *DeleteOrganizationRobotRequest) (*DeleteOrganizationRobotResponse, error)
	// Federation per organization: the OpenID Connect issuers an organization trusts to sign its
	// robots in — a CI system's — and its robots' bindings to their subjects. A token for the
	// organization carries its ID as the audience (OrganizationIssuers.audience). Its owners trust,
	// distrust, bind, and unbind; its members list. ok reaches an issuer over HTTPS, at a public
	// address.
	TrustIssuer(context.Context, *OrganizationIssuerRequest) (*OrganizationIssuers, error)
	DistrustIssuer(context.Context, *OrganizationIssuerRequest) (*OrganizationIssuers, error)
	ListIssuers(context.Context, *ListIssuersRequest) (*OrganizationIssuers, error)
	BindOrganizationRobot(context.Context, *OrganizationRobotBindingRequest) (*OrganizationRobot, error)
	UnbindOrganizationRobot(context.Context, *OrganizationRobotBindingRequest) (*OrganizationRobot, error)
	// An enterprise organization's own identity provider (docs/hosted.md, "Enterprise
	// organizations"): its system of record — Google Workspace, Entra ID, LDAP, or SCIM — which
	// provisions and deprovisions its people (named <handle>-<org>) and syncs its groups as its
	// teams; and its single sign-on, OpenID Connect. Its owners set it (secrets kept sealed: one left
	// empty keeps what was set), read it (secrets never answered), sync it at once, remove it, and
	// reset its SCIM token. An installation's is its configuration's.
	SetIdentityProvider(context.Context, *SetIdentityProviderRequest) (*IdentityProviderInfo, error)
	GetIdentityProvider(context.Context, *IdentityProviderRequest) (*IdentityProviderInfo, error)
	SyncIdentityProvider(context.Context, *IdentityProviderRequest) (*IdentityProviderInfo, error)
	RemoveIdentityProvider(context.Context, *IdentityProviderRequest) (*RemoveIdentityProviderResponse, error)
	ResetSCIMToken(context.Context, *IdentityProviderRequest) (*ResetSCIMTokenResponse, error)
	// ReserveRepository makes a repository's entry, creating, for a person who may make repositories
	// of its owner (or fork its parent): the SCM's, before it makes the repository's storage.
	ReserveRepository(context.Context, *ReserveRepositoryRequest) (*RepositoryEntry, error)
	// ActivateRepository marks an entry active once its storage is made; AbandonRepository removes
	// one whose storage could not be. The SCM's.
	ActivateRepository(context.Context, *RepositoryRef) (*RepositoryEntry, error)
	AbandonRepository(context.Context, *RepositoryRef) (*AbandonRepositoryResponse, error)
	// Expired repositories — deleted more than 30 days ago, or still being made after an hour — are
	// the SCM's to remove (docs/hosted.md, "Deleting, renaming, transferring"): it lists them, asks
	// again of each by the directory's clock, deletes its storage, then purges the entry — a deleted
	// one's purge logged for the other roles to delete what they hold. Nothing brings an expired
	// repository back: neither a restore nor its creation resumed.
	ListExpiredRepositories(context.Context, *ListExpiredRepositoriesRequest) (*ListExpiredRepositoriesResponse, error)
	GetExpiry(context.Context, *RepositoryRef) (*Expiry, error)
	PurgeRepository(context.Context, *RepositoryRef) (*Expiry, error)
	// ResolveRepository is the repository an owner's name names — or names no longer, a redirect
	// answering — as the caller may see it; NOT_FOUND otherwise.
	ResolveRepository(context.Context, *ResolveRepositoryRequest) (*RepositoryEntry, error)
	GetRepositoryEntry(context.Context, *RepositoryRef) (*RepositoryEntry, error)
	// ListRepositoryEntries lists an owner's repositories the caller may see.
	ListRepositoryEntries(context.Context, *ListRepositoryEntriesRequest) (*ListRepositoryEntriesResponse, error)
	// Search finds repositories, people, and organizations by part of their names — owner/name to
	// narrow a repository by its owner — as the caller, or the person ok control names, may see
	// them: the closest first (docs/hosted.md, "ok control at scale, as built").
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// UpdateRepository changes who proposes (maintain), and its visibility (admin).
	UpdateRepository(context.Context, *UpdateRepositoryRequest) (*RepositoryEntry, error)
	// RenameRepository and TransferRepository move it (admin), its old name redirecting; a transfer
	// is to an owner the caller may make repositories of.
	RenameRepository(context.Context, *RenameRepositoryEntryRequest) (*RepositoryEntry, error)
	TransferRepository(context.Context, *TransferRepositoryRequest) (*RepositoryEntry, error)
	// DeleteRepository soft-deletes it (admin); RestoreRepository brings it back within 30 days.
	DeleteRepository(context.Context, *RepositoryRef) (*RepositoryEntry, error)
	RestoreRepository(context.Context, *RepositoryRef) (*RepositoryEntry, error)
	// Grants are a repository's admins' to set and list.
	ListGrants(context.Context, *RepositoryRef) (*ListGrantsResponse, error)
	SetGrant(context.Context, *SetGrantRequest) (*SetGrantResponse, error)
	RemoveGrant(context.Context, *RemoveGrantRequest) (*RemoveGrantResponse, error)
	mustEmbedUnimplementedTenancyServer()
}

